#!/usr/bin/env python3
"""Compare a Release Please module pack with verified Hub content.

WIPPYPACK v1 envelopes contain packed_at/version/build identity, and embedded
files contain ModTime. These fields cannot establish source equality. Compare
entries, meaningful module metadata and resource content instead; never rewrite
an artifact or substitute this digest for the Hub's whole-artifact digest.
"""
from __future__ import annotations

import hashlib
import os
import struct
import subprocess
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

import msgpack
import yaml
import zstandard

PACKED_AT = '2000-01-01T00:00:00Z'
# Registry ownership and resource_count are generated by `pack --module` but
# absent from publish. Resource presence is compared through the actual trees.
ENVELOPE_FIELDS = {'packed_at', 'version', 'wippy_version', 'wippy_commit', 'wippy_date', 'registry', 'resource_count'}


def canonical(value):
    if isinstance(value, dict):
        return {key: canonical(value[key]) for key in sorted(value, key=lambda k: msgpack.packb(k))}
    if isinstance(value, list):
        return [canonical(item) for item in value]
    return value


def pack_content(path: Path) -> dict:
    data = path.read_bytes()
    if len(data) < 284 or data[:12] != b'WIPPYPACK\x01\x00\x00':
        raise ValueError(f'{path}: unsupported pack format/version')
    index_offset, index_size = struct.unpack('<QQ', data[-16:])
    if index_offset < 268 or index_offset + index_size != len(data) - 16:
        raise ValueError(f'{path}: invalid pack index bounds')

    def decompress(raw):
        try:
            decoder = zstandard.ZstdDecompressor().decompressobj()
            value = decoder.decompress(raw)
            if not decoder.eof or decoder.unused_data:
                raise ValueError('incomplete or trailing compressed frame')
            return value
        except zstandard.ZstdError as exc:
            raise ValueError(f'{path}: invalid compressed frame') from exc

    index = msgpack.unpackb(decompress(data[index_offset:index_offset + index_size]), raw=False)
    if set(index) != {'Metadata', 'Entries', 'Resources', 'DataFrames'}:
        raise ValueError(f'{path}: unsupported pack index fields')

    def frame(desc, compressed=True):
        start, size = desc['Offset'], desc['Size']
        if start < 268 or start + size > index_offset:
            raise ValueError(f'{path}: invalid frame bounds')
        raw = data[start:start + size]
        if hashlib.sha256(raw).hexdigest() != desc['Hash']:
            raise ValueError(f'{path}: frame hash mismatch')
        value = decompress(raw) if compressed else raw
        if len(value) != desc['UncompressedSize']:
            raise ValueError(f'{path}: frame size mismatch')
        return value

    metadata = msgpack.unpackb(frame(index['Metadata']), raw=False)
    entries = msgpack.unpackb(frame(index['Entries']), raw=False, strict_map_key=False)
    # DataFrames hold individually compressed file bytes, not a zstd frame.
    for desc in index['DataFrames'] or []:
        frame(desc, compressed=False)
    resources = []
    for resource in index['Resources'] or []:
        if resource['Type'] != 'tree':
            raise ValueError(f'{path}: unsupported resource type {resource["Type"]}')
        tree = msgpack.unpackb(frame(resource['Frame']), raw=False, strict_map_key=False)
        files = {}
        for name, file in tree['Files'].items():
            # Hash is over the uncompressed file contents. Storage coordinates,
            # compression settings and checkout/build times are not file content.
            files[name] = {k: v for k, v in file.items()
                           if k not in {'ModTime', 'Location', 'Compressed', 'CompressedSize'}}
        tree['Files'] = files
        resources.append({'resource': {k: v for k, v in resource.items() if k != 'Frame'}, 'tree': tree})
    payload = {
        'metadata': {key: value for key, value in metadata.items() if key not in ENVELOPE_FIELDS},
        'entries': sorted(entries, key=lambda entry: (entry['ID']['ns'], entry['ID']['name'])),
        'resources': sorted(resources, key=lambda item: (item['resource']['ID']['ns'], item['resource']['ID']['name'])),
    }
    return payload


def content_digest(path: Path) -> str:
    return hashlib.sha256(msgpack.packb(canonical(pack_content(path)), use_bin_type=True)).hexdigest()


class HubRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        redirected = super().redirect_request(req, fp, code, msg, headers, newurl)
        if redirected is not None:
            original = urllib.parse.urlsplit(req.full_url)
            target = urllib.parse.urlsplit(newurl)
            if (original.scheme, original.netloc) != (target.scheme, target.netloc):
                redirected.remove_header('Authorization')
        return redirected


def request(url: str, token: str | None, *, binary=False):
    headers = {'Accept': 'application/octet-stream' if binary else 'application/json'}
    if token:
        headers['Authorization'] = f'Bearer {token}'
    opener = urllib.request.build_opener(HubRedirectHandler())
    with opener.open(urllib.request.Request(url, headers=headers), timeout=60) as response:
        data = response.read()
    if binary:
        return data
    import json
    return json.loads(data)


def module_url(registry, identity):
    return f'{registry.rstrip("/")}/api/v1/modules/{urllib.parse.quote(identity, safe="/")}'


def latest_module(registry, identity, token):
    try:
        return request(module_url(registry, identity), token)
    except urllib.error.HTTPError as exc:
        if exc.code == 404:
            return None
        raise


def download_pack(registry, identity, version, digest, token, destination):
    url = f'{module_url(registry, identity)}/versions/{urllib.parse.quote(version, safe="")}/download'
    data = request(url, token, binary=True)
    if hashlib.sha256(data).hexdigest() != digest.removeprefix('sha256:'):
        raise ValueError(f'{identity}@{version}: Hub artifact digest mismatch')
    destination.write_bytes(data)


def build_pack(module: Path, work: Path, version: str, embeds: list[str]) -> Path:
    work.mkdir(parents=True, exist_ok=True)
    manifest = yaml.safe_load((module / 'wippy.yaml').read_text())
    identity = f'{manifest["organization"]}/{manifest["module"]}'
    lock = work / 'wippy.lock'
    lock.write_text(yaml.safe_dump({'directories': {'modules': '.wippy', 'src': 'empty'},
                                   'modules': [{'name': identity, 'version': version}]}))
    config = work / '.wippy.yaml'
    config.write_text(yaml.safe_dump({'version': '1.0', 'workspace': {'replacements': {identity: str(module)}}}))
    output = work / 'module.wapp'
    args = ['wippy', 'pack', '--lock-file', str(lock), '--config', str(config),
            '--module', identity, '--meta', f'packed_at={PACKED_AT}']
    for embed in embeds:
        args.extend(['--embed', embed])
    subprocess.run([*args, str(output)], check=True)
    return output


def credentials(registry=None):
    path = Path(os.environ.get('XDG_CONFIG_HOME', Path.home() / '.config')) / 'wippy/credentials.yaml'
    try:
        config = yaml.safe_load(path.read_text()) if path.exists() else {}
    except yaml.YAMLError:
        raise ValueError('cannot parse Wippy credentials file') from None
    if not isinstance(config, dict):
        raise ValueError('Wippy credentials file must contain a mapping')
    registry = registry or os.environ.get('WIPPY_REGISTRY') or config.get('default') or 'https://hub.wippy.ai'
    entry = (config.get('credentials') or {}).get(registry) or {}
    return registry, os.environ.get('WIPPY_TOKEN') or entry.get('token')



def unchanged_content(module: dict, version: str) -> bool:
    import tempfile
    root = Path(__file__).resolve().parents[2]
    identity = f'{module["organization"]}/{module["module"]}'
    registry, token = credentials()
    latest = latest_module(registry, identity, token)
    with tempfile.TemporaryDirectory(prefix='release-content-') as directory:
        work = Path(directory)
        local = build_pack(root / module['path'], work / 'local', version, module['embed'])
        digest = content_digest(local)
        print(f'{identity}: local content sha256:{digest}', flush=True)
        if latest is None:
            print(f'{identity}: new module (packed; publish required)', flush=True)
            return False
        published_version = latest['latest_version']
        if not published_version:
            raise ValueError(f'{identity}: Hub module has no latest version')
        details = request(f'{module_url(registry, identity)}/versions/{urllib.parse.quote(published_version, safe="")}', token)
        remote = work / 'hub.wapp'
        download_pack(registry, identity, published_version, details['digest'], token, remote)
        remote_digest = content_digest(remote)
        print(f'{identity}@{published_version}: Hub content sha256:{remote_digest}', flush=True)
        unchanged = (digest == remote_digest and latest['module_type'] == module['type']
                     and latest['visibility'] == module['visibility'] and not details['yanked'])
        if unchanged:
            print(f'{identity}: unchanged (content matches verified Hub artifact)', flush=True)
        else:
            print(f'{identity}: changed (packed; publish required)', flush=True)
        return unchanged
